function check(input, actual) {
  const [n, paths] = input;
  if (!Array.isArray(actual) || actual.length !== n) return false;
  if (actual.some(type => type !== 1 && type !== 2 && type !== 3 && type !== 4)) return false;
  return paths.every(([x, y]) => actual[x - 1] !== actual[y - 1]);
}

validator:
function validate([n, paths]) {
  if (n < 1 || n > 10000) return 'n is between 1 and 10000.';
  if (paths.length > 20000) return 'There are at most 20000 paths.';
  const degree = new Array(n + 1).fill(0);
  for (const path of paths) {
    if (path.length !== 2) return 'Each path joins exactly two gardens.';
    const [x, y] = path;
    if (x < 1 || x > n || y < 1 || y > n) return 'Gardens are numbered 1 to n.';
    if (x === y) return 'A path joins two different gardens.';
    degree[x]++;
    degree[y]++;
    if (degree[x] > 3 || degree[y] > 3) return 'Each garden is on at most 3 paths.';
  }
  return null;
}

