function gardenNoAdj(n, paths) {
  const neighbors = Array.from({ length: n + 1 }, () => []);
  for (const [x, y] of paths) {
    neighbors[x].push(y);
    neighbors[y].push(x);
  }
  const answer = new Array(n).fill(0);
  for (let garden = 1; garden <= n; garden++) {
    const used = new Set();
    for (const next of neighbors[garden]) {
      used.add(answer[next - 1]);
    }
    let flower = 1;
    while (used.has(flower)) {
      flower++;
    }
    answer[garden - 1] = flower;
  }
  return answer;
}

