function gardenNoAdj(n, paths) {
  // Backtracking: try the types from 4 down to 1 for each garden, checking every path to an earlier garden.
  const answer = new Array(n).fill(0);
  const fits = (g, type) => paths.every(([x, y]) => !((x === g && answer[y - 1] === type) || (y === g && answer[x - 1] === type)));
  const place = g => {
    if (g > n) return true;
    for (let type = 4; type >= 1; type--) {
      if (!fits(g, type)) continue;
      answer[g - 1] = type;
      if (place(g + 1)) return true;
      answer[g - 1] = 0;
    }
    return false;
  };
  place(1);
  return answer;
}

