function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const degree = new Array(n + 1).fill(0);
  const seen = new Set();
  const paths = [];
  const limit = large ? 2000 : 12;
  const add = (x, y) => {
    if (x === y || degree[x] >= 3 || degree[y] >= 3 || paths.length >= limit) return;
    const key = Math.min(x, y) * 100000 + Math.max(x, y);
    if (seen.has(key)) return;
    seen.add(key);
    degree[x]++;
    degree[y]++;
    paths.push(rand() < 0.5 ? [x, y] : [y, x]);
  };
  // Some groups of four gardens are all joined to each other, which forces all four types.
  const label = Array.from({ length: n }, (_, i) => i + 1).sort(() => rand() - 0.5);
  const cliques = large ? Math.floor(rand() * 60) : (n >= 4 && rand() < 0.3 ? 1 : 0);
  for (let c = 0; c < cliques && 4 * c + 4 <= n; c++) {
    const group = label.slice(4 * c, 4 * c + 4);
    for (let i = 0; i < 4; i++) for (let j = i + 1; j < 4; j++) add(group[i], group[j]);
  }
  const tries = large ? 3 * n : Math.floor(rand() * 3 * n);
  for (let t = 0; t < tries; t++) add(1 + Math.floor(rand() * n), 1 + Math.floor(rand() * n));
  // Shuffle so the cliques are not listed first.
  for (let i = paths.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [paths[i], paths[j]] = [paths[j], paths[i]];
  }
  return [n, paths];
}
